event_subscription.code:
learnPatternSub_ = smApp->bus().subscribe("sample_browser.learn_pattern_from_audio", [this](const juce::var& v){
    if (!v.isObject()) return;
    auto* o = v.getDynamicObject();
    juce::String filePath = o->getProperty("file").toString();
    juce::File audioFile(filePath);
    if (audioFile.existsAsFile()) {
        learnPatternFromAudio(audioFile);
    }
});

